  1→import { test, expect, Browser, Page } from '@playwright/test';
  2→import { generatePrivateKey, privateKeyToAccount, type PrivateKeyAccount } from 'viem/accounts';
  3→import {
  4→  setupMockWallet,
  5→  loginViaWallet,
  6→  createWalletContext,
  7→} from '../utils/wallet-login-helpers';
  8→import { FileListPage } from '../page-objects/file-browser/file-list.page';
  9→import { UploadZonePage } from '../page-objects/file-browser/upload-zone.page';
 10→import { ContextMenuPage } from '../page-objects/file-browser/context-menu.page';
 11→import { BreadcrumbsPage } from '../page-objects/file-browser/breadcrumbs.page';
 12→import { SelectionActionBarPage } from '../page-objects/file-browser/selection-action-bar.page';
 13→import { CreateFolderDialogPage } from '../page-objects/dialogs/create-folder-dialog.page';
 14→import { RenameDialogPage } from '../page-objects/dialogs/rename-dialog.page';
 15→import { ConfirmDialogPage } from '../page-objects/dialogs/confirm-dialog.page';
 16→import { MoveDialogPage } from '../page-objects/dialogs/move-dialog.page';
 17→import { TextEditorDialogPage } from '../page-objects/dialogs/text-editor-dialog.page';
 18→import { createTestTextFile, createTestBinaryFile, cleanupTestFiles } from '../utils/test-files';
 19→
 20→/**
 21→ * Load Test — Concurrent Users Against Staging
 22→ *
 23→ * Each client gets a unique wallet (keypair) injected via EIP-6963 mock provider.
 24→ * Full auth flow: wallet → SIWE sign → Core Kit → key reconstruction → vault init.
 25→ * Then drives ~50+ file operations that each trigger IPNS publishes.
 26→ *
 27→ * Usage:
 28→ *   cd tests/e2e
 29→ *   pnpm exec playwright test tests/load-test.spec.ts --config=playwright.load.config.ts
 30→ *
 31→ * Env vars:
 32→ *   LOAD_TEST_CLIENTS=5   Number of concurrent clients (default: 3)
 33→ */
 34→
 35→const NUM_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '3', 10);
 36→
 37→// Generous timeouts — multiple clients hitting staging concurrently
 38→test.setTimeout(600_000); // 10 minutes
 39→
 40→interface LoadClient {
 41→  id: number;
 42→  account: PrivateKeyAccount;
 43→  page: Page;
 44→  context: Awaited<ReturnType<Browser['newContext']>>;
 45→  fileList: FileListPage;
 46→  uploadZone: UploadZonePage;
 47→  contextMenu: ContextMenuPage;
 48→  breadcrumbs: BreadcrumbsPage;
 49→  selectionBar: SelectionActionBarPage;
 50→  createFolderDialog: CreateFolderDialogPage;
 51→  renameDialog: RenameDialogPage;
 52→  confirmDialog: ConfirmDialogPage;
 53→  moveDialog: MoveDialogPage;
 54→  textEditor: TextEditorDialogPage;
 55→}
 56→
 57→// Operation timeout — each individual UI action
 58→const OP_TIMEOUT = 30_000;
 59→
 60→// ─── Helpers ───────────────────────────────────────────────────────────────
 61→
 62→/**
 63→ * Recover page to a known state: dismiss any open modals/menus, navigate to root.
 64→ * Called after a failed op to prevent cascading failures.
 65→ */
 66→async function resetState(client: LoadClient): Promise<void> {
 67→  try {
 68→    // Press Escape a few times to dismiss modals/menus/dialogs
 69→    for (let i = 0; i < 3; i++) {
 70→      await client.page.keyboard.press('Escape');
 71→      await client.page.waitForTimeout(200);
 72→    }
 73→    // Click on an empty area to deselect
 74→    await client.page.mouse.click(0, 0);
 75→    await client.page.waitForTimeout(300);
 76→    // Navigate to root if breadcrumbs are visible
 77→    const breadcrumbVisible = await client.breadcrumbs.container().isVisible().catch(() => false);
 78→    if (breadcrumbVisible) {
 79→      await client.breadcrumbs.clickBreadcrumb('my vault').catch(() => {});
 80→      await client.page.waitForTimeout(1000);
 81→    }
 82→  } catch {
 83→    // Best-effort reset — if the page is completely broken, subsequent ops will also fail
 84→  }
 85→}
 86→
 87→/** Safe wrapper for operations — logs failures but doesn't abort the run */
 88→async function op(
 89→  client: LoadClient,
 90→  description: string,
 91→  fn: () => Promise<void>
 92→): Promise<boolean> {
 93→  try {
 94→    await fn();
 95→    console.log(`    [C${client.id}] ✓ ${description}`);
 96→    return true;
 97→  } catch (err) {
 98→    console.warn(`    [C${client.id}] ✗ ${description}: ${(err as Error).message.slice(0, 120)}`);
 99→    await resetState(client);
100→    return false;
101→  }
102→}
103→
104→/** Navigate to root via breadcrumbs */
105→async function goToRoot(client: LoadClient): Promise<void> {
106→  await client.breadcrumbs.clickBreadcrumb('my vault');
107→  await client.page.waitForTimeout(1000);
108→}
109→
110→/** Navigate into a subfolder */
111→async function enterFolder(client: LoadClient, folderName: string): Promise<void> {
112→  await client.fileList.doubleClickFolder(folderName);
113→  await client.breadcrumbs.waitForPathToContain(folderName, { timeout: OP_TIMEOUT });
114→}
115→
116→/** Create a folder via the UI */
117→async function createFolder(client: LoadClient, name: string): Promise<void> {
118→  // Ensure the new folder button is ready
119→  await client.page.locator('.file-browser-new-folder-button').waitFor({ state: 'visible', timeout: 10_000 });
120→  await client.page.locator('.file-browser-new-folder-button').click();
121→  await client.createFolderDialog.waitForOpen({ timeout: 5000 });
122→  await client.createFolderDialog.createFolder(name);
123→  await client.fileList.waitForItemToAppear(name, { timeout: OP_TIMEOUT });
124→}
125→
126→/** Upload a file and wait for it to appear */
127→async function uploadFile(client: LoadClient, filePath: string, fileName: string): Promise<void> {
128→  await client.uploadZone.uploadFile(filePath);
129→  await client.uploadZone.waitForUploadComplete({ timeout: OP_TIMEOUT });
130→  await client.fileList.waitForItemToAppear(fileName, { timeout: OP_TIMEOUT });
131→}
132→
133→/** Right-click → Rename */
134→async function renameItem(client: LoadClient, oldName: string, newName: string): Promise<void> {
135→  await client.fileList.rightClickItem(oldName);
136→  await client.contextMenu.waitForOpen({ timeout: 5000 });
137→  await client.contextMenu.clickRename();
138→  await client.renameDialog.waitForOpen({ timeout: 5000 });
139→  await client.renameDialog.rename(newName);
140→  await client.fileList.waitForItemToAppear(newName, { timeout: OP_TIMEOUT });
141→}
142→
143→/** Right-click → Move to folder */
144→async function moveItem(client: LoadClient, itemName: string, destFolder: string): Promise<void> {
145→  await client.fileList.rightClickItem(itemName);
146→  await client.contextMenu.waitForOpen({ timeout: 5000 });
147→  await client.contextMenu.clickMove();
148→  await client.moveDialog.waitForOpen({ timeout: 5000 });
149→  // Use .first() to avoid strict mode violation when folder names are substrings
150→  // of other folder names (e.g., "c1-data" matching both "c1-data" and "c1-data-sub")
151→  await client.moveDialog.getFolderItem(destFolder).first().click();
152→  await client.moveDialog.clickMove();
153→  await client.moveDialog.waitForClose();
154→  await client.fileList.waitForItemToDisappear(itemName, { timeout: OP_TIMEOUT });
155→}
156→
157→/** Right-click → Delete (with confirm) */
158→async function deleteItem(client: LoadClient, itemName: string): Promise<void> {
159→  await client.fileList.rightClickItem(itemName);
160→  await client.contextMenu.waitForOpen({ timeout: 5000 });
161→  await client.contextMenu.clickDelete();
162→  await client.confirmDialog.waitForOpen({ timeout: 5000 });
163→  await client.confirmDialog.clickConfirm();
164→  await client.fileList.waitForItemToDisappear(itemName, { timeout: OP_TIMEOUT });
165→}
166→
167→/** Right-click → Edit text file → modify → save */
168→async function editTextFile(client: LoadClient, fileName: string, newContent: string): Promise<void> {
169→  await client.fileList.rightClickItem(fileName);
170→  await client.contextMenu.waitForOpen({ timeout: 5000 });
171→  await client.contextMenu.clickEdit();
172→  // Allow extra time for file decryption on staging (IPNS resolve + download + decrypt)
173→  await client.textEditor.waitForOpen({ timeout: OP_TIMEOUT });
174→  await client.textEditor.waitForContentLoaded({ timeout: OP_TIMEOUT });
175→  await client.textEditor.setContent(newContent);
176→  await client.textEditor.clickSave();
177→  // Wait for save to complete (button text changes back from "Saving...")
178→  await client.page.waitForFunction(
179→    () => {
180→      const btn = document.querySelector('.text-editor-modal .dialog-button--primary');
181→      return btn && !btn.textContent?.includes('Saving');
182→    },
183→    { timeout: OP_TIMEOUT }
184→  );
185→  await client.textEditor.close();
186→}
187→
188→/** Delete account by calling the API from within the page context.
189→ *  Uses fetch with credentials to send the refresh token cookie,
190→ *  gets a fresh access token, then calls DELETE /auth/account. */
191→async function deleteAccount(client: LoadClient): Promise<void> {
192→  // Discover the API base URL from the app's runtime config
193→  const apiBase = await client.page.evaluate(() => {
194→    // Vite injects env vars at build time — read from the same source as apiClient
195→    return (window as any).__VITE_API_URL
196→      || document.querySelector('meta[name="api-url"]')?.getAttribute('content')
197→      || 'https://api-staging.cipherbox.cc';
198→  });
199→
200→  const deleted = await client.page.evaluate(async (apiUrl: string) => {
201→    // Step 1: Refresh to get a fresh access token (uses HTTP-only cookie)
202→    const refreshRes = await fetch(`${apiUrl}/auth/refresh`, {
203→      method: 'POST',
204→      credentials: 'include',
205→    });
206→    if (!refreshRes.ok) return { ok: false, step: 'refresh', status: refreshRes.status };
207→    const { accessToken } = await refreshRes.json();
208→
209→    // Step 2: Delete the account
210→    const deleteRes = await fetch(`${apiUrl}/auth/account`, {
211→      method: 'DELETE',
212→      credentials: 'include',
213→      headers: {
214→        'Authorization': `Bearer ${accessToken}`,
215→        'Content-Type': 'application/json',
216→      },
217→      body: JSON.stringify({ confirmation: 'DELETE' }),
218→    });
219→    return { ok: deleteRes.ok, step: 'delete', status: deleteRes.status };
220→  }, apiBase);
221→
222→  if (!deleted.ok) {
223→    throw new Error(`Account deletion failed at ${deleted.step}: HTTP ${deleted.status}`);
224→  }
225→}
226→
227→/** Multi-select items and batch move */
228→async function batchMove(
229→  client: LoadClient,
230→  itemNames: string[],
231→  destFolder: string
232→): Promise<void> {
233→  // Select first item normally, then Ctrl+click the rest
234→  await client.fileList.selectItem(itemNames[0]);
235→  for (let i = 1; i < itemNames.length; i++) {
236→    await client.fileList.ctrlClickItem(itemNames[i]);
237→  }
238→  await client.selectionBar.waitForVisible({ timeout: 5000 });
239→  await client.selectionBar.clickMove();
240→  await client.moveDialog.waitForOpen({ timeout: 5000 });
241→  await client.moveDialog.getFolderItem(destFolder).first().click();
242→  await client.moveDialog.clickMove();
243→  await client.moveDialog.waitForClose();
244→  // Wait for all items to disappear from current view
245→  for (const name of itemNames) {
246→    await client.fileList.waitForItemToDisappear(name, { timeout: OP_TIMEOUT });
247→  }
248→}
249→
250→/** Multi-select items and batch delete */
251→async function batchDelete(client: LoadClient, itemNames: string[]): Promise<void> {
252→  await client.fileList.selectItem(itemNames[0]);
253→  for (let i = 1; i < itemNames.length; i++) {
254→    await client.fileList.ctrlClickItem(itemNames[i]);
255→  }
256→  await client.selectionBar.waitForVisible({ timeout: 5000 });
257→  await client.selectionBar.clickDelete();
258→  await client.confirmDialog.waitForOpen({ timeout: 5000 });
259→  await client.confirmDialog.clickConfirm();
260→  for (const name of itemNames) {
261→    await client.fileList.waitForItemToDisappear(name, { timeout: OP_TIMEOUT });
262→  }
263→}
264→
265→// ─── Main client workload ──────────────────────────────────────────────────
266→
267→/**
268→ * Full workload for a single client. ~50+ operations, each triggering IPNS publish.
269→ *
270→ * Structure:
271→ *   Phase 1: Create folder hierarchy (5 folders + 2 subfolders)     →  7 publishes
272→ *   Phase 2: Upload small text files (15 files across folders)      → 15 publishes
273→ *   Phase 3: Upload medium binary files (10 files)                  → 10 publishes
274→ *   Phase 4: Upload large binary files (5 files, 100KB–500KB)       →  5 publishes
275→ *   Phase 5: Edit text files (5 edits)                              →  5 publishes
276→ *   Phase 6: Rename items (8 renames: files + folders)              →  8 publishes
277→ *   Phase 7: Move items between folders (6 individual moves)        →  6 publishes
278→ *   Phase 8: Batch move (2 batches of 3 files)                      →  2 publishes
279→ *   Phase 9: Batch delete (2 batches of 3–4 files)                  →  2 publishes
280→ *   Phase 10: Individual deletes + cleanup (remaining items)        → ~10 publishes
281→ *                                                             Total: ~70 publishes
282→ */
283→async function runClientWorkload(client: LoadClient): Promise<{ succeeded: number; failed: number }> {
284→  const { id } = client;
285→  const prefix = `c${id}`;
286→  let succeeded = 0;
287→  let failed = 0;
288→
289→  const count = (ok: boolean) => { if (ok) succeeded++; else failed++; };
290→
291→  // ─── Warm-up: first mutation after login races with initial sync polling.
292→  // Create and delete a dummy folder to let the sync settle.
293→  await op(client, 'Warm-up folder', async () => {
294→    await createFolder(client, `${prefix}-warmup`);
295→    await deleteItem(client, `${prefix}-warmup`);
296→  });
297→
298→  // ─── Phase 1: Create folder hierarchy ────────────────────────────────
299→  console.log(`  [C${id}] Phase 1: Creating folder hierarchy...`);
300→
301→  const folders = ['docs', 'images', 'data', 'archive', 'temp'];
302→  const folderNames = folders.map((f) => `${prefix}-${f}`);
303→
304→  for (const name of folderNames) {
305→    count(await op(client, `Create folder ${name}`, () => createFolder(client, name)));
306→  }
307→
308→  // Create subfolders inside 'docs' and 'data'
309→  const subfolders = [
310→    { parent: folderNames[0], name: `${prefix}-docs-sub` },
311→    { parent: folderNames[2], name: `${prefix}-data-sub` },
312→  ];
313→  for (const sub of subfolders) {
314→    count(
315→      await op(client, `Create subfolder ${sub.name}`, async () => {
316→        await enterFolder(client, sub.parent);
317→        await createFolder(client, sub.name);
318→        await goToRoot(client);
319→      })
320→    );
321→  }
322→
323→  // ─── Phase 2: Upload small text files ────────────────────────────────
324→  console.log(`  [C${id}] Phase 2: Uploading 15 small text files...`);
325→
326→  const textFiles: { name: string; path: string; folder: string | null }[] = [];
327→  // 5 files at root
328→  for (let i = 1; i <= 5; i++) {
329→    const f = createTestTextFile(
330→      `${prefix}-note-${i}.txt`,
331→      `Client ${id} note ${i}. Timestamp: ${Date.now()}. ${'Lorem ipsum dolor sit amet. '.repeat(10)}`
332→    );
333→    textFiles.push({ name: f.name, path: f.path, folder: null });
334→  }
335→  // 5 files in docs folder
336→  for (let i = 1; i <= 5; i++) {
337→    const f = createTestTextFile(
338→      `${prefix}-doc-${i}.txt`,
339→      `Document ${i} from client ${id}. ${'Content block. '.repeat(20)}`
340→    );
341→    textFiles.push({ name: f.name, path: f.path, folder: folderNames[0] });
342→  }
343→  // 5 files in data folder
344→  for (let i = 1; i <= 5; i++) {
345→    const f = createTestTextFile(
346→      `${prefix}-log-${i}.txt`,
347→      `Log entry ${i}: ${new Date().toISOString()} client=${id} ${'data '.repeat(50)}`
348→    );
349→    textFiles.push({ name: f.name, path: f.path, folder: folderNames[2] });
350→  }
351→
352→  // Upload root files
353→  for (const tf of textFiles.filter((f) => !f.folder)) {
354→    count(await op(client, `Upload ${tf.name}`, () => uploadFile(client, tf.path, tf.name)));
355→  }
356→  // Upload into docs
357→  count(
358→    await op(client, `Navigate to ${folderNames[0]}`, () => enterFolder(client, folderNames[0]))
359→  );
360→  for (const tf of textFiles.filter((f) => f.folder === folderNames[0])) {
361→    count(await op(client, `Upload ${tf.name}`, () => uploadFile(client, tf.path, tf.name)));
362→  }
363→  count(await op(client, 'Back to root', () => goToRoot(client)));
364→
365→  // Upload into data
366→  count(
367→    await op(client, `Navigate to ${folderNames[2]}`, () => enterFolder(client, folderNames[2]))
368→  );
369→  for (const tf of textFiles.filter((f) => f.folder === folderNames[2])) {
370→    count(await op(client, `Upload ${tf.name}`, () => uploadFile(client, tf.path, tf.name)));
371→  }
372→  count(await op(client, 'Back to root', () => goToRoot(client)));
373→
374→  // ─── Phase 3: Upload medium binary files ─────────────────────────────
375→  console.log(`  [C${id}] Phase 3: Uploading 10 medium binary files (10–50KB)...`);
376→
377→  const mediumFiles: { name: string; path: string }[] = [];
378→  for (let i = 1; i <= 10; i++) {
379→    const sizeKb = 10 + Math.floor(Math.random() * 40); // 10-50KB
380→    const f = createTestBinaryFile(sizeKb, `${prefix}-medium-${i}.bin`);
381→    mediumFiles.push({ name: f.name, path: f.path });
382→  }
383→
384→  // Upload half to root, half to images folder
385→  for (const mf of mediumFiles.slice(0, 5)) {
386→    count(await op(client, `Upload ${mf.name}`, () => uploadFile(client, mf.path, mf.name)));
387→  }
388→  count(
389→    await op(client, `Navigate to ${folderNames[1]}`, () => enterFolder(client, folderNames[1]))
390→  );
391→  for (const mf of mediumFiles.slice(5)) {
392→    count(await op(client, `Upload ${mf.name}`, () => uploadFile(client, mf.path, mf.name)));
393→  }
394→  count(await op(client, 'Back to root', () => goToRoot(client)));
395→
396→  // ─── Phase 4: Upload large binary files ──────────────────────────────
397→  console.log(`  [C${id}] Phase 4: Uploading 5 large binary files (100–500KB)...`);
398→
399→  const largeFiles: { name: string; path: string }[] = [];
400→  const largeSizes = [100, 200, 300, 400, 500];
401→  for (let i = 0; i < 5; i++) {
402→    const f = createTestBinaryFile(largeSizes[i], `${prefix}-large-${i + 1}.bin`);
403→    largeFiles.push({ name: f.name, path: f.path });
404→  }
405→
406→  for (const lf of largeFiles) {
407→    count(await op(client, `Upload ${lf.name} (${largeSizes[largeFiles.indexOf(lf)]}KB)`, () =>
408→      uploadFile(client, lf.path, lf.name)
409→    ));
410→  }
411→
412→  // ─── Phase 5: Re-upload files (overwrite triggers IPNS publish) ─────
413→  // Text editor dialog is unreliable on staging (IPNS resolve for file
414→  // content hangs). Re-uploading with same filename overwrites the file,
415→  // which equally triggers metadata update + IPNS publish.
416→  console.log(`  [C${id}] Phase 5: Re-uploading 5 files (overwrite)...`);
417→
418→  for (let i = 1; i <= 5; i++) {
419→    const f = createTestTextFile(
420→      `${prefix}-note-${i}.txt`,
421→      `EDITED by client ${id} at ${new Date().toISOString()}. Revision ${i}.\n${'Updated content block. '.repeat(30)}`
422→    );
423→    count(await op(client, `Re-upload ${f.name}`, () => uploadFile(client, f.path, f.name)));
424→  }
425→
426→  // ─── Phase 6: Rename items ───────────────────────────────────────────
427→  console.log(`  [C${id}] Phase 6: Renaming 8 items...`);
428→
429→  // Rename 5 root files
430→  for (let i = 1; i <= 5; i++) {
431→    const oldName = `${prefix}-note-${i}.txt`;
432→    const newName = `${prefix}-renamed-note-${i}.txt`;
433→    count(await op(client, `Rename ${oldName} → ${newName}`, () => renameItem(client, oldName, newName)));
434→  }
435→
436→  // Rename 2 folders
437→  count(
438→    await op(client, `Rename folder ${folderNames[4]}`, () =>
439→      renameItem(client, folderNames[4], `${prefix}-renamed-temp`)
440→    )
441→  );
442→  count(
443→    await op(client, `Rename folder ${folderNames[3]}`, () =>
444→      renameItem(client, folderNames[3], `${prefix}-renamed-archive`)
445→    )
446→  );
447→
448→  // Rename a large file
449→  count(
450→    await op(client, `Rename ${largeFiles[0].name}`, () =>
451→      renameItem(client, largeFiles[0].name, `${prefix}-renamed-large.bin`)
452→    )
453→  );
454→
455→  // ─── Phase 7: Move items between folders ─────────────────────────────
456→  console.log(`  [C${id}] Phase 7: Moving 6 items individually...`);
457→
458→  // Move renamed notes into docs folder
459→  for (let i = 1; i <= 3; i++) {
460→    const fileName = `${prefix}-renamed-note-${i}.txt`;
461→    count(
462→      await op(client, `Move ${fileName} → ${folderNames[0]}`, () =>
463→        moveItem(client, fileName, folderNames[0])
464→      )
465→    );
466→  }
467→
468→  // Move medium files into renamed-archive
469→  for (let i = 1; i <= 3; i++) {
470→    const fileName = mediumFiles[i - 1].name;
471→    count(
472→      await op(client, `Move ${fileName} → ${prefix}-renamed-archive`, () =>
473→        moveItem(client, fileName, `${prefix}-renamed-archive`)
474→      )
475→    );
476→  }
477→
478→  // ─── Phase 8: Batch move ─────────────────────────────────────────────
479→  console.log(`  [C${id}] Phase 8: Batch moving files...`);
480→
481→  // Batch move remaining medium root files into renamed-temp
482→  const remainingMedium = mediumFiles.slice(3, 5).map((f) => f.name);
483→  if (remainingMedium.length >= 2) {
484→    count(
485→      await op(client, `Batch move ${remainingMedium.length} files → ${prefix}-renamed-temp`, () =>
486→        batchMove(client, remainingMedium, `${prefix}-renamed-temp`)
487→      )
488→    );
489→  }
490→
491→  // Batch move large files (2-4) into data folder
492→  const largesToMove = largeFiles.slice(1, 4).map((f) => f.name);
493→  if (largesToMove.length >= 2) {
494→    count(
495→      await op(client, `Batch move ${largesToMove.length} large files → ${folderNames[2]}`, () =>
496→        batchMove(client, largesToMove, folderNames[2])
497→      )
498→    );
499→  }
500→
501→  // ─── Phase 9: Batch delete ───────────────────────────────────────────
502→  console.log(`  [C${id}] Phase 9: Batch deleting files...`);
503→
504→  // Navigate to renamed-archive and batch delete the 3 medium files we moved there
505→  count(
506→    await op(client, `Navigate to ${prefix}-renamed-archive`, () =>
507→      enterFolder(client, `${prefix}-renamed-archive`)
508→    )
509→  );
510→  const archiveFiles = mediumFiles.slice(0, 3).map((f) => f.name);
511→  if (archiveFiles.length >= 2) {
512→    count(
513→      await op(client, `Batch delete ${archiveFiles.length} files from archive`, () =>
514→        batchDelete(client, archiveFiles)
515→      )
516→    );
517→  }
518→  count(await op(client, 'Back to root', () => goToRoot(client)));
519→
